#nullable enable
using Marten;
using Marten.Schema;
using Campaigns.Contracts;

namespace Campaigns;

/// <summary>
/// A world to run the app against by hand. NOT used by the tests — they have their own SeedData with fixed
/// ids, because a test needs a world it controls and a demo needs one that looks used.
///
/// Attached via <c>.InitializeWith(...)</c> on the Marten chain; registering an IInitialData in the DI
/// container alone does nothing.
///
/// What this is FOR here: five read models, two of them not documents at all, and one of them Async. Booting
/// the app with real data is how you see that the flat table's migration ran and that the async daemon
/// actually processes — neither of which a green suite alone would tell you if the daemon were unregistered.
/// </summary>
public sealed class GenesisData : IInitialData
{
    // Fixed, so a hand-written query or a second run can name the same things.
    private static readonly Guid Campaign = Guid.Parse("aaaaaaaa-0000-0000-0000-000000000001");
    private static readonly Guid Sender = Guid.Parse("aaaaaaaa-0000-0000-0000-000000000002");
    private static readonly Guid FirstMessage = Guid.Parse("aaaaaaaa-0000-0000-0000-000000000003");
    private static readonly Guid SecondMessage = Guid.Parse("aaaaaaaa-0000-0000-0000-000000000004");
    private static readonly DateTimeOffset At = new(2026, 1, 15, 9, 0, 0, TimeSpan.Zero);

    public async Task Populate(IDocumentStore store, CancellationToken cancellation)
    {
        // Populate runs on EVERY startup, so this has to be idempotent. Guarding on the EVENT STREAM rather
        // than on a view: a view can be rebuilt or its recipe changed, and a guard that reads one would then
        // re-seed onto a stream that already has the events.
        await using var session = store.LightweightSession();

        var existing = await session.Events.FetchStreamStateAsync(Campaign, cancellation);
        if (existing is not null) return;

        session.Events.StartStream(Campaign, new CampaignOpened(Campaign, "January newsletter", At));

        // Two messages from one sender in one month, so SenderMonthly has something to roll up, and one of
        // them with several recipients so DeliveryLog has more than one row for it.
        session.Events.StartStream(FirstMessage, new MessageQueued(
            FirstMessage, Campaign, Sender, "Welcome",
            ["ana@example.com", "bo@example.com", "cy@example.com"], At));

        session.Events.StartStream(SecondMessage, new MessageQueued(
            SecondMessage, Campaign, Sender, "Reminder", ["ana@example.com"], At.AddHours(2)));

        // One of each outcome, so every counter in every view is non-zero and a wrong fold is visible rather
        // than hidden behind a column of zeroes.
        session.Events.Append(FirstMessage,
            new MessageDelivered(FirstMessage, "ana@example.com", At.AddMinutes(1)),
            new MessageBounced(FirstMessage, "bo@example.com", "mailbox full", At.AddMinutes(2)));

        await session.SaveChangesAsync(cancellation);
    }
}
